package com.vandorlabs.neoforge.screen;
import com.google.gson.*;
import com.vandorlabs.screen.ScreenFamily;
import net.minecraft.nbt.*;
/** Independently frozen source surface setters, including preserved sleeping pulse deadlines. */
public final class ScreenSurfaceEditChecks {
 public static void main(String[] args)throws Exception{JsonObject reference;try(var reader=java.nio.file.Files.newBufferedReader(java.nio.file.Path.of(System.getProperty("screenSurfaceEditsReference")))){reference=JsonParser.parseReader(reader).getAsJsonObject();}int cases=0;var catalog=NativeScreenCatalog.INSTANCE;for(var entry:reference.getAsJsonArray("cases")){var row=entry.getAsJsonObject();int slot=row.get("slot").getAsInt();String key=slot==0?"RedstonePrimary":"RedstoneSecondary";CompoundTag before=TagParser.parseTag(row.get("before").getAsString()),source=TagParser.parseTag(row.get("after").getAsString());var old=NativeScreenSettings.read(before,catalog);var result=new NativeScreenSurfaceEdit(slot,row.get("choice").getAsInt()).apply(ScreenFamily.fromId(row.get("id").getAsString()),old,catalog);if(result==null||result.rowsEnabled()!=source.getCompound(key).getBoolean("Enabled"))throw new AssertionError("Surface enable differs");CompoundTag actual=new CompoundTag();result.settings().write(actual);for(String field:actual.getAllKeys())if(!java.util.Objects.equals(actual.get(field),source.get(field)))throw new AssertionError("Surface differs "+row.get("id")+" field="+field);if(before.getCompound(key).getList("Rows",10).getCompound(0).getLong("PulseUntil")!=source.getCompound(key).getList("Rows",10).getCompound(0).getLong("PulseUntil"))throw new AssertionError("Source dormant deadline changed");cases++;}if(cases!=1080||!reference.get("sha256").getAsString().equals("3ad6efab083e3af4dd19c0a4db94d2ee2fca4f0acb9364224614bfd7b90dad20"))throw new AssertionError("Source surface coverage");for(int deferred:new int[]{-4,-3})try{new NativeScreenSurfaceEdit(0,deferred);throw new AssertionError("Deferred surface accepted");}catch(IllegalArgumentException expected){}System.out.println("Native Screen surface edits PASS actual Source profiles="+cases+" deferred installations refused");}
}
